      <g className="t-fumes">
        <circle cx="92" cy="232" r="6" fill={fg} opacity="0.4" />
        <circle cx="76" cy="222" r="9" fill={fg} opacity="0.25" />
        <circle cx="60" cy="218" r="12" fill={fg} opacity="0.15" />
      </g>
      {/* Container truck */}
